package ro.leo.visual;
import android.content.*;import java.io.*;import java.util.*;import org.json.*;import android.util.Base64;
/** One private checkpoint of visual settings and wallpaper only. */
final class ThemeCheckpoint {
 static File file(Context c){return new File(c.getFilesDir(),"theme-previous.json");}
 static Set<String> keys(){Set<String> keys=new HashSet<String>(Arrays.asList("theme","accent","unified-phone","large-text","warm","list"));for(String app:StyleSettingsActivity.APPS)keys.add("app-theme-"+app);return keys;}
 static void save(Context c)throws Exception{JSONObject out=new JSONObject(),values=new JSONObject();Map<String,?> source=c.getSharedPreferences("appearance",0).getAll();for(String key:keys())if(source.containsKey(key))values.put(key,source.get(key));File wallpaper=Appearance.wallpaper(c);out.put("settings",values).put("wallpaper",wallpaper.isFile()?Base64.encodeToString(BackupEngine.bytes(wallpaper,2097152),Base64.NO_WRAP):JSONObject.NULL);BackupEngine.write(file(c),out.toString().getBytes("UTF-8"));}
 static void restore(Context c)throws Exception{JSONObject out=new JSONObject(new String(BackupEngine.atomicBytes(file(c),3145728),"UTF-8"));JSONObject values=out.getJSONObject("settings");for(Iterator<String> i=values.keys();i.hasNext();){String key=i.next();if(!keys().contains(key)||!(values.get(key) instanceof Boolean||values.get(key) instanceof Integer))throw new IOException();}if(out.isNull("wallpaper"))new android.util.AtomicFile(Appearance.wallpaper(c)).delete();else{byte[] bytes=Base64.decode(out.getString("wallpaper"),Base64.DEFAULT);if(bytes.length>2097152)throw new IOException();BackupEngine.write(Appearance.wallpaper(c),bytes);}SharedPreferences.Editor e=c.getSharedPreferences("appearance",0).edit();for(String key:keys())e.remove(key);for(Iterator<String> i=values.keys();i.hasNext();){String key=i.next();Object value=values.get(key);if(value instanceof Boolean)e.putBoolean(key,(Boolean)value);else e.putInt(key,((Number)value).intValue());}if(!e.commit())throw new IOException();}
 static void apply(Context c,int pack,boolean full)throws Exception{save(c);try{if(full)StockWallpapers.apply(c,new int[]{2,1,3,2}[pack]);ThemePacks.apply(c,pack);if(full&&!c.getSharedPreferences("appearance",0).edit().putBoolean("large-text",false).commit())throw new IOException();}catch(Exception e){restore(c);throw e;}}
}
